import {
  BrowserRouter,
  Routes,
  Route
} from 'react-router-dom';

import Products from './pages/Products';
import AdminDashboard from './pages/AdminDashboard';

function App() {
  return (
    <BrowserRouter>

      <Routes>

        <Route path='/' element={<Products />} />

        <Route
          path='/admin'
          element={<AdminDashboard />}
        />

      </Routes>

    </BrowserRouter>
  );
}

export default App;
